/ {
	aliases {
		test-gpio-0 = &gpio0;
		test-gpio-1 = &gpio1;
		test-adc-0 = &adc0;
		test-adc-1 = &adc1;
		test-dac-0 = &dac0;
		test-dma-0 = &dma0;
		test-i2c-0 = &i2c0;
		test-pwm-0 = &pwm0;
		test-spi-0 = &spi0;
		test-uart-0 = &uart0;
		test-reg = &test_reg;
		test-inst-0 = &test_inst_0;
		test-inst-1 = &test_inst_1;
		test-inst-2 = &test_inst_2;
		test-inst-3 = &test_inst_3;
		test-inst-4 = &test_inst_4;
		test-inst-5 = &test_inst_5;
		test-inst-6 = &test_inst_6;
		test-inst-7 = &test_inst_7;
		test-inst-8 = &test_inst_8;
		test-inst-9 = &test_inst_9;
		test-inst-a = &test_inst_a;
		test-inst-b = &test_inst_b;
		test-inst-c = &test_inst_c;
		test-inst-d = &test_inst_d;
		test-inst-e = &test_inst_e;
		test-inst-f = &test_inst_f;
		test-phandle-array = &test_phandle_array;
		test-phandle-array-with-name = &test_phandle_array_with_name;
		test-interrupts = &test_interrupts;
		test-interrupt-parent = &test_interrupt_parent;
		test-temp = &temp_sensor;
		test-io-channel-ctlr-1 = &adc1;
		test-io-channel-ctlr-2 = &adc2;
	};

	test_inst_0: test-inst-0 {
		compatible = "vnd,test-inst";
		reg = <0>;
	};
	test_inst_1: test-inst-1 {
		compatible = "vnd,test-inst";
		reg = <1>;
	};
	test_inst_2: test-inst-2 {
		compatible = "vnd,test-inst";
		reg = <2>;
	};
	test_inst_3: test-inst-3 {
		compatible = "vnd,test-inst";
		reg = <3>;
	};
	test_inst_4: test-inst-4 {
		compatible = "vnd,test-inst";
		reg = <4>;
	};
	test_inst_5: test-inst-5 {
		compatible = "vnd,test-inst";
		reg = <5>;
	};
	test_inst_6: test-inst-6 {
		compatible = "vnd,test-inst";
		reg = <6>;
	};
	test_inst_7: test-inst-7 {
		compatible = "vnd,test-inst";
		reg = <7>;
	};
	test_inst_8: test-inst-8 {
		compatible = "vnd,test-inst";
		reg = <8>;
	};
	test_inst_9: test-inst-9 {
		compatible = "vnd,test-inst";
		reg = <9>;
	};
	test_inst_a: test-inst-a {
		compatible = "vnd,test-inst";
		reg = <0xa>;
	};
	test_inst_b: test-inst-b {
		compatible = "vnd,test-inst";
		reg = <0xb>;
	};
	test_inst_c: test-inst-c {
		compatible = "vnd,test-inst";
		reg = <0xc>;
	};
	test_inst_d: test-inst-d {
		compatible = "vnd,test-inst";
		reg = <0xd>;
	};
	test_inst_e: test-inst-e {
		compatible = "vnd,test-inst";
		reg = <0xe>;
	};
	test_inst_f: test-inst-f {
		compatible = "vnd,test-inst";
		reg = <0xf>;
	};

	test_reg: test-reg {
		compatible = "vnd,test-reg";
		reg = <0x1000 0x100>, <0x2000 0x200>;
		reg-names = "foo", "bar";
	};

	test_phandle_array: test-phandle-array {
		compatible = "vnd,test-phandle-array";
		phandles = <&test_inst_0 &test_inst_1 &test_inst_2>;
	};

	test_phandle_array_with_name: test-phandle-array-with-name {
		compatible = "vnd,test-phandle-array-with-name";
		phandle-names = "foo", "bar", "baz";
		phandles = <&test_inst_0 &test_inst_1 &test_inst_2>;
	};

	test_interrupt_parent: test-interrupt-parent {
		compatible = "vnd,test-interrupt-parent";
		interrupt-controller;
		#interrupt-cells = <2>;
	};

	test_interrupts: test-interrupts {
		compatible = "vnd,test-interrupts";
		interrupt-parent = <&test_interrupt_parent>;
		interrupts = <1 2>, <3 4>;
		interrupt-names = "foo", "bar";
	};

	temp_sensor: temp-sensor {
		compatible = "vnd,temp-sensor";
		io-channels = <&adc1 0>, <&adc2 1>;
	};

	adc1: adc@1 {
		compatible = "vnd,adc";
		reg = <1>;
		#io-channel-cells = <1>;
	};

	adc2: adc@2 {
		compatible = "vnd,adc";
		reg = <2>;
		#io-channel-cells = <1>;
	};
};
